const items = $input.all();
const now = new Date().toISOString().split('T')[0];

return items.map(item => {
  return {
    json: {
      Department: item.json.department,
      'Total Records': item.json.total_records,
      'Total Revenue': `$${Number(item.json.total_revenue).toLocaleString()}`,
      'Avg Score': Number(item.json.avg_score).toFixed(2),
      'Report Date': now
    }
  };
});
